- Anpassung: $R_\mathrm{a} = R_\mathrm{i} = 15 \Omega$
\begin{align*}
P_\mathrm{a} &= \frac{\left(\frac{U_\mathrm{q}}{2}\right)^2}{R_\mathrm{i}} = \frac{{U_\mathrm{q}}^2}{4 R_\mathrm{i}}= 60 \mathrm{W}
\end{align*}

- \[
\eta = \frac{P_\mathrm{a}}{P_\mathrm{i} + P_\mathrm{a}} = \frac{I^2 R_\mathrm{a}}{I^2 R_\mathrm{i} + I^2 R_\mathrm{a}} = \frac{R_\mathrm{a}}{R_\mathrm{i} + R_\mathrm{a}}
\]
\[\Rightarrow \eta R_\mathrm{i} + \eta R_\mathrm{a} = R_\mathrm{a}
\Rightarrow R_\mathrm{a}=R_\mathrm{i} \frac{\eta}{1-\eta}=285\Omega
\]

\begin{align*}
P_\mathrm{i} &= I^2 R_\mathrm{i} = \dfrac{U_\mathrm{q}^2 R_\mathrm{i}}{(R_\mathrm{i} + R_\mathrm{a})^2} = \dfrac{U_\mathrm{q}^2 R_\mathrm{i}}{\left(R_\mathrm{i} + R_\mathrm{i} \frac{\eta}{1-\eta} \right)^2} 

P_\mathrm{i} &= \dfrac{U_\mathrm{q}^2}{R_\mathrm{i}} \cdot \dfrac{1}{\left(\frac{1-\eta + \eta}{1- \eta}\right)^2}= \frac{U_\mathrm{q}^2}{R_\mathrm{i}}(1-\eta)^2= 0,6\mathrm{W} 

P_\mathrm{a} &= I^2 R_\mathrm{a} = \frac{{U_\mathrm{q}}^2 R_\mathrm{a}}{(R_\mathrm{i} + R_\mathrm{a})^2} = \dfrac{U_\mathrm{q}^2 R_\mathrm{i}\frac{\eta}{1-\eta} }{\left(R_\mathrm{i} + R_\mathrm{i} \frac{\eta}{1-\eta}\right)^2} 

P_\mathrm{a} &= \dfrac{U_\mathrm{q}^2}{R_\mathrm{i}} \cdot \dfrac{\eta (1-\eta)}{1-\eta + \eta} = \dfrac{U_\mathrm{q}^2}{R_\mathrm{i}}\eta (1-\eta) = 11,4\mathrm{W}
\end{align*}

- \begin{align*}
P_\mathrm{i} &= \dfrac{U_\mathrm{q}^2 R_\mathrm{i}}{(R_\mathrm{i} + R_\mathrm{a})^2} \leq P_\mathrm{izul} 

(R_\mathrm{i} + R_\mathrm{a})^2 &\geq \dfrac{U_\mathrm{q}^2 R_\mathrm{i}}{P_\mathrm{izul}} 

R_\mathrm{a} &\geq \sqrt{\dfrac{U_\mathrm{q}^2 R_\mathrm{i}}{P_\mathrm{izul}}} - R_\mathrm{i} 

R_\mathrm{a} &\geq \underbrace{R_\mathrm{i} \left(\dfrac{U_\mathrm{q}}{\sqrt{P_\mathrm{izul}R_\mathrm{i}}}-1\right)}_{ R_\mathrm{azul}}=27,4\Omega

P_\mathrm{a}(R_\mathrm{azul}) &= \dfrac{U_\mathrm{q}^2 R_\mathrm{azul}}{\left(R_\mathrm{i} + R_\mathrm{azul}\right)^2}= \dfrac{U_\mathrm{q}^2 R_\mathrm{i}\left(\dfrac{U_\mathrm{q}}{\sqrt{P_\mathrm{izul}R_\mathrm{i}}}-1\right) }{\dfrac{U_\mathrm{q}^2 R_\mathrm{i}}{P_\mathrm{izul}}} 

P_\mathrm{a}(R_\mathrm{azul}) &= P_\mathrm{izul}\left(\dfrac{U_\mathrm{q}}{\sqrt{P_\mathrm{izul}R_\mathrm{i}}}-1\right) = 54,8\mathrm{W}
\end{align*}

\hinw{Diesen Fall bezeichnet man als Überanpassung. Infolge des flachen Maximums von $P_\mathrm{a}(R_\mathrm{a})$ 
ist bei Überanpassung die Einbuße an abgegebener Leistung $P_\mathrm{a}$ verhältnismäßig gering.}

Mit der Normierung $ P_{q0} = \frac{{U_\mathrm{q}}^2}{R_\mathrm{i}}$ folgt

\begin{align*}
\frac{P_\mathrm{a}}{P_{q0}} &= \frac{ \frac{R_\mathrm{a}}{R_\mathrm{i}}}{\left(1 + \frac{R_\mathrm{a}}{R_\mathrm{i}}\right)^2}.
\end{align*}

